   441→//   row.int_vals[0] = 1;      // id
   442→//   row.str_vals[0] = "Alice"; // name
   443→//   row.int_vals[1] = 30;     // age
   444→//   row.bool_vals[0] = true;  // active
   445→//   let id, ok = t.table_insert(row);
   446→//
