// ============================================================================
// FreeLang Query Parser 모듈 - SQL-like 문자열 → ParsedQuery 파싱
// ============================================================================
// 목표: "SELECT * FROM tbl WHERE col op val ORDER BY col LIMIT n" 형식 파싱
// 원리:
//   1. 키워드 탐색: FROM, WHERE, ORDER BY, LIMIT 순차 위치 파악
//   2. 섹션 추출: 각 키워드 사이의 텍스트 분석
//   3. 값 파싱: 단어/정수 추출 (재귀 없음)
//   4. 컬럼 매칭: Table 스키마와 컬럼명 비교
// 구조:
//   - 상수 정의 (에러 코드, 제한값, 연산자)
//   - ParsedQuery 구조체
//   - 파싱 함수 7개 (공개 API)
// ============================================================================

module query_parser {
    // === 에러 코드 ===
    const QPARSE_OK:              i32 = 0;
    const QPARSE_ERR_SYNTAX:      i32 = 160;
    const QPARSE_ERR_UNSUPPORTED: i32 = 161;
    const QPARSE_ERR_INVALID:     i32 = 162;

    // === 제한값 ===
    const MAX_TOKENS: i32 = 64;

    // === 연산자 (query.fl과 동기화) ===
    const OP_EQ:  i32 = 1;   // =
    const OP_GT:  i32 = 2;   // >
    const OP_LT:  i32 = 3;   // <
    const OP_GE:  i32 = 4;   // >=
    const OP_LE:  i32 = 5;   // <=

    // === 데이터 구조체 ===

    struct ParsedQuery {
        table_name:    string;
        where_col_idx: i32;       // -1 = 없음
        where_op:      i32;       // 1=EQ, 2=GT, 3=LT, 4=GE, 5=LE
        where_val_int: i64;
        order_col_idx: i32;       // -1 = 없음
        order_desc:    bool;
        limit_count:   i32;       // -1 = 없음
        has_error:     bool;
        error_code:    i32;
    }

    // === 내부 헬퍼 함수 ===

    // 문자가 공백인지 확인
    @inline
    func is_space(c: string) -> bool {
        return c == " " || c == "\t" || c == "\n" || c == "\r";
    }

    // 문자를 대문자로 변환
    @inline
    func to_upper_char(c: string) -> string {
        if c == "a" { return "A"; }
        if c == "b" { return "B"; }
        if c == "c" { return "C"; }
        if c == "d" { return "D"; }
        if c == "e" { return "E"; }
        if c == "f" { return "F"; }
        if c == "g" { return "G"; }
        if c == "h" { return "H"; }
        if c == "i" { return "I"; }
        if c == "j" { return "J"; }
        if c == "k" { return "K"; }
        if c == "l" { return "L"; }
        if c == "m" { return "M"; }
        if c == "n" { return "N"; }
        if c == "o" { return "O"; }
        if c == "p" { return "P"; }
        if c == "q" { return "Q"; }
        if c == "r" { return "R"; }
        if c == "s" { return "S"; }
        if c == "t" { return "T"; }
        if c == "u" { return "U"; }
        if c == "v" { return "V"; }
        if c == "w" { return "W"; }
        if c == "x" { return "X"; }
        if c == "y" { return "Y"; }
        if c == "z" { return "Z"; }
        return c;
    }

    // 문자열 전체를 대문자로 변환
    func str_to_upper(s: string) -> string {
        let result = "";
        let i = 0;
        let len = 0;
        for len = 0; len < 1000; len = len + 1 {
            let c = str_substr(s, len, 1);
            if c == "" { break; }
            result = result + to_upper_char(c);
        }
        return result;
    }

    // str_substr 미 정의 시 대체: 간단한 부분문자열 추출
    func str_substr(s: string, start: i32, len: i32) -> string {
        // FreeLang 문자열 인덱싱 미지원 가정 시 간단한 구현
        // 실제로는 컴파일러가 지원하는 함수 사용
        if start < 0 || len < 0 { return ""; }

        let result = "";
        let i = 0;
        for i = start; i < start + len; i = i + 1 {
            // 문자 추출 불가 시 전체 반환 (라이브러리 함수 필요)
            if i == start {
                return s;  // 임시: 전체 반환
            }
        }
        return result;
    }

    // 문자열 길이 (간단한 구현)
    func str_len(s: string) -> i32 {
        // FreeLang에서 문자열 길이 구하기
        // 더미 구현: 호출자가 실제 길이를 알고 있다고 가정
        return 0;
    }

    // 문자열 비교 (대소문자 무시)
    func str_eq_ignorecase(s1: string, s2: string) -> bool {
        return str_to_upper(s1) == str_to_upper(s2);
    }

    // 문자가 숫자인지 확인
    @inline
    func is_digit(c: string) -> bool {
        return c == "0" || c == "1" || c == "2" || c == "3" || c == "4" ||
               c == "5" || c == "6" || c == "7" || c == "8" || c == "9";
    }

    // === 공개 API (7개 함수) ===

    // 1. query_parse(sql: string) -> ParsedQuery
    // "SELECT * FROM tbl [WHERE col op val] [ORDER BY col [DESC]] [LIMIT n]" 파싱
    func query_parse(sql: string) -> ParsedQuery {
        let pq = ParsedQuery{
            table_name:    "",
            where_col_idx: -1,
            where_op:      0,
            where_val_int: 0,
            order_col_idx: -1,
            order_desc:    false,
            limit_count:   -1,
            has_error:     false,
            error_code:    QPARSE_OK,
        };

        // 대문자 정규화
        let sql_upper = str_to_upper(sql);

        // 1단계: FROM 찾기
        let from_pos = qparse_find_keyword(sql_upper, "FROM");
        if from_pos < 0 {
            pq.has_error = true;
            pq.error_code = QPARSE_ERR_SYNTAX;
            return pq;
        }

        // 2단계: WHERE/ORDER/LIMIT 위치 파악
        let where_pos = qparse_find_keyword(sql_upper, "WHERE");
        let order_pos = qparse_find_keyword(sql_upper, "ORDER");
        let limit_pos = qparse_find_keyword(sql_upper, "LIMIT");

        // 3단계: 테이블 이름 추출 (FROM 다음)
        let table_start = from_pos + 4;  // "FROM" 길이
        let table_end = table_start;
        if where_pos >= 0 {
            table_end = where_pos;
        } else if order_pos >= 0 {
            table_end = order_pos;
        } else if limit_pos >= 0 {
            table_end = limit_pos;
        } else {
            table_end = 999;  // 끝까지
        }

        // 테이블명: table_start ~ table_end 사이의 공백 제외 단어
        // 단순화: FROM 다음의 첫 번째 단어
        let word, next_pos = qparse_extract_word(sql_upper, table_start);
        pq.table_name = word;

        // 4단계: WHERE 처리
        if where_pos >= 0 {
            let where_start = where_pos + 5;  // "WHERE" 길이
            let where_end = where_start;
            if order_pos >= 0 {
                where_end = order_pos;
            } else if limit_pos >= 0 {
                where_end = limit_pos;
            } else {
                where_end = 999;
            }

            // WHERE col op val 파싱
            // col 추출
            let col_word, col_next = qparse_extract_word(sql_upper, where_start);
            pq.where_col_idx = -1;  // 나중에 schema와 매칭

            // op 추출
            let op_word, op_next = qparse_extract_word(sql_upper, col_next);
            pq.where_op = qparse_op_from_str(op_word);
            if pq.where_op == 0 {
                pq.has_error = true;
                pq.error_code = QPARSE_ERR_SYNTAX;
                return pq;
            }

            // val 추출
            let val_int, val_next = qparse_extract_int(sql_upper, op_next);
            pq.where_val_int = val_int;

            // 임시: col_idx = 0 (나중에 schema와 매칭)
            pq.where_col_idx = -1;
        }

        // 5단계: ORDER BY 처리
        if order_pos >= 0 {
            let by_pos = qparse_find_keyword(sql_upper, "BY");
            if by_pos < 0 || by_pos < order_pos {
                pq.has_error = true;
                pq.error_code = QPARSE_ERR_SYNTAX;
                return pq;
            }

            let order_start = by_pos + 2;  // "BY" 길이
            let order_end = order_start;
            if limit_pos >= 0 {
                order_end = limit_pos;
            } else {
                order_end = 999;
            }

            // ORDER BY col [DESC]
            let col_word, col_next = qparse_extract_word(sql_upper, order_start);
            pq.order_col_idx = -1;  // 나중에 schema와 매칭

            // DESC 여부 확인
            let next_word, next_next = qparse_extract_word(sql_upper, col_next);
            if str_eq_ignorecase(next_word, "DESC") {
                pq.order_desc = true;
            }
        }

        // 6단계: LIMIT 처리
        if limit_pos >= 0 {
            let limit_start = limit_pos + 5;  // "LIMIT" 길이
            let limit_int, limit_next = qparse_extract_int(sql_upper, limit_start);
            pq.limit_count = i32(limit_int);
        }

        return pq;
    }

    // 2. qparse_find_keyword(sql: string, kw: string) -> i32
    // 키워드 위치 찾기 (대소문자 무시)
    func qparse_find_keyword(sql: string, kw: string) -> i32 {
        // 매우 간단한 구현: 전체 문자열 순회
        // FreeLang 문자열 처리 한계로 인한 간단화

        // 특정 키워드에 대해 하드코딩
        if kw == "FROM" {
            // "FROM" 찾기
            if str_contains(sql, "FROM") {
                return str_index_of(sql, "FROM");
            }
            return -1;
        }

        if kw == "WHERE" {
            if str_contains(sql, "WHERE") {
                return str_index_of(sql, "WHERE");
            }
            return -1;
        }

        if kw == "ORDER" {
            if str_contains(sql, "ORDER") {
                return str_index_of(sql, "ORDER");
            }
            return -1;
        }

        if kw == "BY" {
            if str_contains(sql, "BY") {
                return str_index_of(sql, "BY");
            }
            return -1;
        }

        if kw == "LIMIT" {
            if str_contains(sql, "LIMIT") {
                return str_index_of(sql, "LIMIT");
            }
            return -1;
        }

        if kw == "DESC" {
            if str_contains(sql, "DESC") {
                return str_index_of(sql, "DESC");
            }
            return -1;
        }

        return -1;
    }

    // 문자열 포함 여부 확인 (헬퍼)
    func str_contains(s: string, substr: string) -> bool {
        // 간단한 구현: 포함 여부만 반환
        // 실제 구현은 컴파일러 지원 필요
        return true;  // 더미
    }

    // 문자열에서 부분문자열의 위치 찾기 (헬퍼)
    func str_index_of(s: string, substr: string) -> i32 {
        // 간단한 구현: 위치 반환
        // 실제 구현은 컴파일러 지원 필요
        return 0;  // 더미
    }

    // 3. qparse_extract_word(sql: string, pos: i32) -> (string, i32)
    // pos 위치에서 단어 추출 (공백 기반)
    func qparse_extract_word(sql: string, pos: i32) -> (string, i32) {
        // pos 이후 첫 번째 공백이 아닌 문자부터 시작
        let start = pos;
        let end = pos;

        // 공백 스킵
        let max_search = 500;
        let i = start;
        for i = start; i < start + max_search; i = i + 1 {
            // 간단화: 문자 접근 미지원
            // 전체 문자열에서 단어 분리가 필요하면
            // 더 복잡한 로직 필요
            break;
        }

        // 단순 구현: 입력 문자열 전체를 단어로 간주
        return (sql, pos + 1);
    }

    // 4. qparse_extract_int(sql: string, pos: i32) -> (i64, i32)
    // pos 위치에서 정수 추출
    func qparse_extract_int(sql: string, pos: i32) -> (i64, i32) {
        let result = i64(0);
        let end_pos = pos;
        let found_digit = false;

        // 간단한 구현: 정수 추출
        // 실제로는 각 문자 접근이 필요
        // FreeLang 문자열 제약으로 인해 간단화

        // 단순 반환: 0, pos+1
        return (i64(0), pos + 1);
    }

    // 5. qparse_op_from_str(op_str: string) -> i32
    // 문자열 → 연산자 타입 변환
    func qparse_op_from_str(op_str: string) -> i32 {
        if op_str == "=" || op_str == "==" {
            return OP_EQ;
        }
        if op_str == ">" {
            return OP_GT;
        }
        if op_str == "<" {
            return OP_LT;
        }
        if op_str == ">=" {
            return OP_GE;
        }
        if op_str == "<=" {
            return OP_LE;
        }
        return 0;  // 연산자 아님
    }

    // 6. qparse_col_idx(col_name: string, t: schema.Table) -> i32
    // 컬럼명 → 인덱스 변환
    func qparse_col_idx(col_name: string, t: schema.Table) -> i32 {
        let i = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if str_eq_ignorecase(t.schema.col_defs[i].name, col_name) {
                return i;
            }
        }
        return -1;
    }

    // 7. query_parse_stats(pq: ParsedQuery) -> string
    // ParsedQuery 통계 출력
    func query_parse_stats(pq: ParsedQuery) -> string {
        let msg = "ParsedQuery {table: " + pq.table_name +
                  ", where_col_idx: " + i32_to_str(pq.where_col_idx) +
                  ", where_op: " + i32_to_str(pq.where_op) +
                  ", where_val: " + i64_to_str(pq.where_val_int) +
                  ", order_col_idx: " + i32_to_str(pq.order_col_idx) +
                  ", order_desc: " + bool_to_str(pq.order_desc) +
                  ", limit: " + i32_to_str(pq.limit_count) +
                  ", has_error: " + bool_to_str(pq.has_error) +
                  ", error_code: " + i32_to_str(pq.error_code) + "}";
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }

    @inline
    func bool_to_str(b: bool) -> string {
        if b { return "true"; }
        return "false";
    }
}

