// ============================================================================
// FreeLang Query Parser 모듈 - SQL-like 문자열 → ParsedQuery 파싱
// ============================================================================
// 목표: "SELECT * FROM tbl WHERE col op val ORDER BY col LIMIT n" 형식 파싱
// 원리:
//   1. 키워드 탐색: FROM, WHERE, ORDER BY, LIMIT 순차 위치 파악
//   2. 섹션 추출: 각 키워드 사이의 텍스트 분석
//   3. 값 파싱: 단어/정수 추출 (char_at 기반, 재귀 없음)
//   4. 컬럼 매칭: Table 스키마와 컬럼명 비교
// 구조:
//   - 상수 정의 (에러 코드, 제한값, 연산자)
//   - ParsedQuery 구조체
//   - Parser 상태 구조체
//   - 파싱 함수 7개 (공개 API)
// ============================================================================

module query_parser {
    // === 에러 코드 ===
    const QPARSE_OK:              i32 = 0;
    const QPARSE_ERR_SYNTAX:      i32 = 160;
    const QPARSE_ERR_UNSUPPORTED: i32 = 161;
    const QPARSE_ERR_INVALID:     i32 = 162;

    // === 제한값 ===
    const MAX_TOKENS: i32 = 64;
    const MAX_WORD_LEN: i32 = 64;

    // === 연산자 (query.fl과 동기화) ===
    const OP_EQ:  i32 = 1;   // =
    const OP_GT:  i32 = 2;   // >
    const OP_LT:  i32 = 3;   // <
    const OP_GE:  i32 = 4;   // >=
    const OP_LE:  i32 = 5;   // <=

    // === 데이터 구조체 ===

    struct ParsedQuery {
        table_name:    string;
        where_col_idx: i32;       // -1 = 없음
        where_op:      i32;       // 1=EQ, 2=GT, 3=LT, 4=GE, 5=LE
        where_val_int: i64;
        order_col_idx: i32;       // -1 = 없음
        order_desc:    bool;
        limit_count:   i32;       // -1 = 없음
        has_error:     bool;
        error_code:    i32;
    }

    // 파서 상태
    struct QParser {
        input: string;
        pos:   i32;
        len:   i32;
    }

    // === 내부 헬퍼 함수 ===

    // 현재 위치의 문자 코드 반환 (범위 초과 시 -1)
    @inline
    func (qp: *QParser) peek() -> i32 {
        if qp.pos >= qp.len {
            return -1;
        }
        return char_at(qp.input, qp.pos);
    }

    // 파서 커서 1칸 진진
    @inline
    func (qp: *QParser) advance() {
        if qp.pos < qp.len {
            qp.pos = qp.pos + 1;
        }
    }

    // 공백 스킵 (space, tab, CR, LF)
    func (qp: *QParser) skip_ws() {
        let c = 0;
        for c = 1; c > 0; {
            c = qp.peek();
            if c == 32 || c == 9 || c == 10 || c == 13 {
                qp.advance();
            } else {
                c = 0;  // break
            }
        }
    }

    // 문자 코드가 대문자 알파벳 범위 (A-Z)
    @inline
    func is_upper_letter(c: i32) -> bool {
        return c >= 65 && c <= 90;
    }

    // 문자 코드가 숫자 (0-9)
    @inline
    func is_digit_code(c: i32) -> bool {
        return c >= 48 && c <= 57;
    }

    // 문자 코드가 알파벳 또는 숫자
    @inline
    func is_alnum(c: i32) -> bool {
        return (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || (c >= 48 && c <= 57) || c == 95;  // _ 포함
    }

    // 소문자를 대문자로 변환 (문자 코드)
    @inline
    func to_upper_code(c: i32) -> i32 {
        if c >= 97 && c <= 122 {  // a-z
            return c - 32;
        }
        return c;
    }

    // === 공개 API (7개 함수) ===

    // 1. query_parse(sql: string) -> ParsedQuery
    // "SELECT * FROM tbl [WHERE col op val] [ORDER BY col [DESC]] [LIMIT n]" 파싱
    func query_parse(sql: string) -> ParsedQuery {
        let pq = ParsedQuery{
            table_name:    "",
            where_col_idx: -1,
            where_op:      0,
            where_val_int: 0,
            order_col_idx: -1,
            order_desc:    false,
            limit_count:   -1,
            has_error:     false,
            error_code:    QPARSE_OK,
        };

        // 파서 초기화
        let qp = QParser{
            input: sql,
            pos:   0,
            len:   0,
        };

        // 문자열 길이 계산 (반복: EOF 전까지)
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(sql, qp.len);
            if ch == -1 {
                c = 0;  // break
            } else {
                qp.len = qp.len + 1;
            }
        }

        // 1단계: FROM 키워드 찾기
        let from_pos = qp_find_keyword(&qp, "FROM");
        if from_pos < 0 {
            pq.has_error = true;
            pq.error_code = QPARSE_ERR_SYNTAX;
            return pq;
        }

        // 2단계: WHERE/ORDER/LIMIT 위치 파악
        let where_pos = qp_find_keyword(&qp, "WHERE");
        let order_pos = qp_find_keyword(&qp, "ORDER");
        let limit_pos = qp_find_keyword(&qp, "LIMIT");

        // 3단계: 테이블 이름 추출 (FROM 다음)
        qp.pos = from_pos + 4;  // "FROM" 길이
        qp.skip_ws();
        let table_word = qp_extract_word_from_parser(&qp);
        pq.table_name = table_word;

        // 4단계: WHERE 처리
        if where_pos >= 0 {
            qp.pos = where_pos + 5;  // "WHERE" 길이
            qp.skip_ws();

            // WHERE col op val 파싱
            let col_word = qp_extract_word_from_parser(&qp);
            qp.skip_ws();

            let op_word = qp_extract_word_from_parser(&qp);
            qp.skip_ws();
            pq.where_op = qparse_op_from_str(op_word);
            if pq.where_op == 0 {
                pq.has_error = true;
                pq.error_code = QPARSE_ERR_SYNTAX;
                return pq;
            }

            let val_int = qp_extract_int_from_parser(&qp);
            pq.where_val_int = val_int;

            // col_idx는 -1로 유지 (나중에 schema와 매칭)
            pq.where_col_idx = -1;
        }

        // 5단계: ORDER BY 처리
        if order_pos >= 0 {
            let by_pos = qp_find_keyword(&qp, "BY");
            if by_pos < 0 || by_pos < order_pos {
                pq.has_error = true;
                pq.error_code = QPARSE_ERR_SYNTAX;
                return pq;
            }

            qp.pos = by_pos + 2;  // "BY" 길이
            qp.skip_ws();

            let col_word = qp_extract_word_from_parser(&qp);
            qp.skip_ws();

            // order_col_idx는 -1로 유지 (나중에 schema와 매칭)
            pq.order_col_idx = -1;

            // DESC 여부 확인
            let next_word = qp_peek_word(&qp);
            if next_word == "DESC" {
                pq.order_desc = true;
            }
        }

        // 6단계: LIMIT 처리
        if limit_pos >= 0 {
            qp.pos = limit_pos + 5;  // "LIMIT" 길이
            qp.skip_ws();

            let limit_int = qp_extract_int_from_parser(&qp);
            pq.limit_count = i32(limit_int);
        }

        return pq;
    }

    // 2. qparse_find_keyword(sql: string, kw: string) -> i32
    // 키워드 위치 찾기 (대소문자 무시)
    func qparse_find_keyword(sql: string, kw: string) -> i32 {
        let qp = QParser{
            input: sql,
            pos:   0,
            len:   0,
        };

        // 문자열 길이 계산
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(sql, qp.len);
            if ch == -1 {
                c = 0;  // break
            } else {
                qp.len = qp.len + 1;
            }
        }

        return qp_find_keyword(&qp, kw);
    }

    // 내부 키워드 찾기 함수
    func qp_find_keyword(qp: *QParser, kw: string) -> i32 {
        let start_pos = 0;
        let kw_len = 0;

        // 키워드 길이 계산
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(kw, kw_len);
            if ch == -1 {
                c = 0;  // break
            } else {
                kw_len = kw_len + 1;
            }
        }

        // 순회: 매 위치에서 키워드 매칭 시도
        let i = 0;
        for i = 0; i <= qp.len - kw_len; i = i + 1 {
            let matches = true;
            let j = 0;
            for j = 0; j < kw_len && matches; j = j + 1 {
                let sql_ch = to_upper_code(char_at(qp.input, i + j));
                let kw_ch = to_upper_code(char_at(kw, j));
                if sql_ch != kw_ch {
                    matches = false;
                }
            }

            if matches {
                // 키워드 앞이 공백 또는 시작인지 확인
                let before_ok = (i == 0) || is_space_code(char_at(qp.input, i - 1));
                // 키워드 뒤가 공백 또는 끝인지 확인
                let after_ok = (i + kw_len >= qp.len) || is_space_code(char_at(qp.input, i + kw_len));

                if before_ok && after_ok {
                    return i;
                }
            }
        }

        return -1;
    }

    // 문자 코드가 공백인지 확인
    @inline
    func is_space_code(c: i32) -> bool {
        return c == 32 || c == 9 || c == 10 || c == 13;
    }

    // 3. qparse_extract_word(sql: string, pos: i32) -> (string, i32)
    // pos 위치에서 단어 추출 (공백 기반)
    func qparse_extract_word(sql: string, pos: i32) -> (string, i32) {
        let qp = QParser{
            input: sql,
            pos:   pos,
            len:   0,
        };

        // 문자열 길이 계산
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(sql, qp.len);
            if ch == -1 {
                c = 0;  // break
            } else {
                qp.len = qp.len + 1;
            }
        }

        qp.skip_ws();
        let word = qp_extract_word_from_parser(&qp);
        return (word, qp.pos);
    }

    // 파서에서 단어 추출
    func qp_extract_word_from_parser(qp: *QParser) -> string {
        let result = "";
        let len = 0;

        for len = 0; len < MAX_WORD_LEN; len = len + 1 {
            let c = qp.peek();
            if c == -1 || is_space_code(c) {
                break;
            }
            let ch = char_from_code(c);
            result = result + ch;
            qp.advance();
        }

        return result;
    }

    // 파서에서 단어 미리보기 (진진하지 않음)
    func qp_peek_word(qp: *QParser) -> string {
        let saved_pos = qp.pos;
        let result = qp_extract_word_from_parser(qp);
        qp.pos = saved_pos;
        return result;
    }

    // 4. qparse_extract_int(sql: string, pos: i32) -> (i64, i32)
    // pos 위치에서 정수 추출
    func qparse_extract_int(sql: string, pos: i32) -> (i64, i32) {
        let qp = QParser{
            input: sql,
            pos:   pos,
            len:   0,
        };

        // 문자열 길이 계산
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(sql, qp.len);
            if ch == -1 {
                c = 0;  // break
            } else {
                qp.len = qp.len + 1;
            }
        }

        qp.skip_ws();
        let result = qp_extract_int_from_parser(&qp);
        return (result, qp.pos);
    }

    // 파서에서 정수 추출
    func qp_extract_int_from_parser(qp: *QParser) -> i64 {
        let result = i64(0);
        let is_negative = false;

        // 음수 확인
        if qp.peek() == 45 {  // '-'
            is_negative = true;
            qp.advance();
        }

        // 숫자 추출
        let c = 0;
        for c = 1; c > 0; {
            c = qp.peek();
            if is_digit_code(c) {
                let digit = i64(c - 48);
                result = result * 10 + digit;
                qp.advance();
            } else {
                c = 0;  // break
            }
        }

        if is_negative {
            result = -result;
        }

        return result;
    }

    // 5. qparse_op_from_str(op_str: string) -> i32
    // 문자열 → 연산자 타입 변환
    func qparse_op_from_str(op_str: string) -> i32 {
        if op_str == "=" || op_str == "==" {
            return OP_EQ;
        }
        if op_str == ">" {
            return OP_GT;
        }
        if op_str == "<" {
            return OP_LT;
        }
        if op_str == ">=" {
            return OP_GE;
        }
        if op_str == "<=" {
            return OP_LE;
        }
        return 0;  // 연산자 아님
    }

    // 6. qparse_col_idx(col_name: string, t: schema.Table) -> i32
    // 컬럼명 → 인덱스 변환
    func qparse_col_idx(col_name: string, t: schema.Table) -> i32 {
        let i = 0;
        for i = 0; i < t.schema.col_count; i = i + 1 {
            if str_eq_ignorecase(col_name, t.schema.col_defs[i].name) {
                return i;
            }
        }
        return -1;
    }

    // 문자열 비교 (대소문자 무시)
    func str_eq_ignorecase(s1: string, s2: string) -> bool {
        let len1 = 0;
        let len2 = 0;

        // 길이 계산
        let c = 0;
        for c = 1; c > 0; {
            let ch = char_at(s1, len1);
            if ch == -1 {
                c = 0;  // break
            } else {
                len1 = len1 + 1;
            }
        }

        for c = 1; c > 0; {
            let ch = char_at(s2, len2);
            if ch == -1 {
                c = 0;  // break
            } else {
                len2 = len2 + 1;
            }
        }

        if len1 != len2 {
            return false;
        }

        // 각 문자 비교
        let i = 0;
        for i = 0; i < len1; i = i + 1 {
            let c1 = to_upper_code(char_at(s1, i));
            let c2 = to_upper_code(char_at(s2, i));
            if c1 != c2 {
                return false;
            }
        }

        return true;
    }

    // 7. query_parse_stats(pq: ParsedQuery) -> string
    // ParsedQuery 통계 출력
    func query_parse_stats(pq: ParsedQuery) -> string {
        let msg = "ParsedQuery {table: " + pq.table_name +
                  ", where_col_idx: " + i32_to_str(pq.where_col_idx) +
                  ", where_op: " + i32_to_str(pq.where_op) +
                  ", where_val: " + i64_to_str(pq.where_val_int) +
                  ", order_col_idx: " + i32_to_str(pq.order_col_idx) +
                  ", order_desc: " + bool_to_str(pq.order_desc) +
                  ", limit: " + i32_to_str(pq.limit_count) +
                  ", has_error: " + bool_to_str(pq.has_error) +
                  ", error_code: " + i32_to_str(pq.error_code) + "}";
        return msg;
    }

    // === 헬퍼 함수 ===

    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }

    @inline
    func bool_to_str(b: bool) -> string {
        if b { return "true"; }
        return "false";
    }
}

